/**
 * @suppress
 */
public object FfiConverterTypeStremioService: FfiConverter<StremioService, Long> {
    override fun lower(value: StremioService): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): StremioService {
        return StremioService(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): StremioService {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: StremioService) = 8UL

    override fun write(value: StremioService, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



/**
 * Represents a Stremio addon with its configuration and metadata.
 *
 * An addon is a remote service that provides content catalogs, metadata, and streams.
 * Each addon has a manifest that describes its capabilities and supported content types.
 */
data class Addon (
    /**
     * Unique identifier for this addon
     */
    var `id`: kotlin.String
    , 
    /**
     * URL to the addon's manifest
     */
    var `manifestUrl`: kotlin.String
    , 
    /**
     * Display name of the addon
     */
    var `name`: kotlin.String
    , 
    /**
     * Addon version string
     */
    var `version`: kotlin.String
    , 
    /**
     * Whether this addon is currently enabled
     */
    var `enabled`: kotlin.Boolean
    , 
    /**
     * Priority for conflict resolution (higher = more priority)
     */
    var `priority`: kotlin.Int
    , 
    /**
     * Original URL before any redirects or transformations
     */
    var `originalUrl`: kotlin.String?
    , 
    /**
     * Whether this addon is currently healthy (responds to requests)
     */
    var `healthy`: kotlin.Boolean
    , 
    /**
     * Number of consecutive health check failures
     */
    var `consecutiveFailures`: kotlin.UInt
    
){
    

    
    companion object
